# PS6 model: the general factor model of lecture L14a, section 'Building a General Factor Model'.
# Students do not edit this file.
#
# This file runs the fitting and sampling algorithms of the lecture, step by step. The calculations
# inside the steps call your functions: least_squares_fit, sector_matrix, compose_growth_rates, and, on
# the Advanced track, economic_factor, unmix_factors, and mix_factors.
#
# The file reads from top to bottom:
#   1. economic_factors    turns the levels of the FRED series into the economic factors x
#   2. fit_factor_model    fitting steps 1, 2, and 3
#   3. fit_jump_model      fits one single-asset jump hidden Markov model (fitting step 5)
#   4. draw_series         draws one synthetic path from a fitted jump hidden Markov model
#   5. synthetic_markets   fitting steps 4 and 5, then the sampling algorithm
#   6. market_statistics   the average correlations that the report compares
#   7. range_statistics    the lowest and the highest value of each average over the synthetic markets
#   8. r_squared           the R² of the table 'FRED series'
#
# The names follow the lecture and the companion:
#   G     the growth rates of the stocks (1/yr), days × stocks: column i holds stock i
#   g_m   the growth rates of SPY (1/yr), one per day
#   x     the economic factors, days × factors (no columns in a model without the FRED series)
#   X     the design matrix [1, g_m, x_1, ..., x_K], days × columns
#   Θ     the baseline, market sensitivity, and economic loadings of each stock: column i holds stock i
#   E     the residual of each stock after fitting step 1, days × stocks
#   B     the sector matrix, stocks × sectors
#   F     the sector factors, days × sectors
#   Δ     the sector loadings of each stock, sectors × stocks: column i holds stock i
#   U     the stock-specific part of each stock, days × stocks
#   Φ     the factor matrix [g_m, x_1, ..., x_K, F], days × factors
#   Z     the uncorrelated factors of the Cholesky step, days × factors
#
# Julia notes for this file:
#   G[:, i]          column i of G, every row; G[t, :] is row t of G, every column
#   size(G, 1)       the number of rows of G; size(G, 2) is the number of columns
#   zeros(n, m)      an n × m matrix of zeros; zeros(n, 0) has n rows and no columns
#   hcat(a, b, c)    puts a, b, and c side by side as the columns of one matrix
#   v = Float64[]    an empty list of numbers; push!(v, a) adds a to the end of the list v
#   (X = X, E = E)   a NamedTuple: a group of values that you read by name, such as fit.X
#   f(a; b = true)   the arguments after the semicolon are keyword arguments, passed by name

"""
    economic_factors(levels::Matrix{Float64}, settings::NamedTuple) -> Matrix{Float64}

Turn each FRED series into a daily economic factor with `economic_factor`.

### Arguments

- `levels`: The levels from `load_fred_levels`, price days × series.
- `settings`: The settings from `load_config`. The function uses `fred_kinds` and `Δt`.

### Returns

- The economic factors, growth-rate days × series: one row fewer than `levels`.
"""
function economic_factors(levels::Matrix{Float64}, settings::NamedTuple)::Matrix{Float64}

    # Make room for the factors: one column per series, and one row per growth-rate day. There is one
    # growth-rate day fewer than price days, because each growth rate needs the price of the day before -
    number_of_series = size(levels, 2);
    x = zeros(size(levels, 1) - 1, number_of_series);

    # Turn column k of the levels into column k of the factors: a daily change for a rate, or a growth
    # rate for a price, as settings.fred_kinds[k] says -
    for k ∈ 1:number_of_series
        x[:, k] = economic_factor(levels[:, k], settings.fred_kinds[k], settings.Δt);
    end
    return x;
end

"""
    fit_factor_model(universe::NamedTuple, x::Matrix{Float64}; sectors::Bool = true) -> NamedTuple

Run fitting steps 1, 2, and 3 of the general factor model. Each step calls `least_squares_fit`.

### Arguments

- `universe`: The market from `load_universe`.
- `x`: The economic factors, days × factors. A matrix with zero columns gives a model without
  economic factors.

### Optional Arguments

- `sectors`: `false` stops after step 1. With no economic factors, this is the single index model.
  Default: `true`.

### Returns

- A `NamedTuple` with the fields:
  - `X`: The design matrix `[1, g_m, x_1, ..., x_K]`, days × columns.
  - `Θ`: The baseline, market sensitivity, and economic loadings of each stock, columns × stocks.
  - `E`: The residual of each stock after step 1, days × stocks.
  - `F`: The sector factors, days × sectors (zero columns without sectors).
  - `Δ`: The sector loadings of each stock, sectors × stocks (zero rows without sectors).
  - `U`: The stock-specific part of each stock, days × stocks.
"""
function fit_factor_model(universe::NamedTuple, x::Matrix{Float64}; sectors::Bool = true)::NamedTuple

    # Initialize: the growth rates G of the stocks, the number of days (rows of G), and the number of
    # stocks (columns of G) -
    G = universe.G;
    number_of_days = size(G, 1);
    number_of_stocks = size(G, 2);

    # The design matrix X = [1, g_m, x_1, ..., x_K]: a column of ones for the baseline, the growth rates
    # of SPY for the market sensitivity, and one column for each economic factor. When x has no columns,
    # X is [1, g_m] -
    X = hcat(ones(number_of_days), universe.g_m, x);

    # Fitting step 1, for each stock i: fit the growth rates of stock i to the columns of X. The fit gives
    # θ = (α_i, β_i, η_i1, ..., η_iK), which goes in column i of Θ. The residual, the part of the growth
    # rates that X θ does not explain, goes in column i of E -
    Θ = zeros(size(X, 2), number_of_stocks);
    E = zeros(number_of_days, number_of_stocks);
    for i ∈ 1:number_of_stocks
        θ = least_squares_fit(X, G[:, i]);
        Θ[:, i] = θ;
        E[:, i] = G[:, i] - X * θ;
    end

    # A model without sectors stops after step 1: F has no columns, Δ has no rows, and the residual of
    # step 1 is the stock-specific part U. copy(E) gives U its own copy of the values in E -
    if sectors == false
        F = zeros(number_of_days, 0);
        Δ = zeros(0, number_of_stocks);
        return (X = X, Θ = Θ, E = E, F = F, Δ = Δ, U = copy(E));
    end

    # Fitting step 2, for each day t: fit the residuals of all the stocks on day t (row t of E) to the
    # sector matrix B. The fit gives one sector factor per sector for day t, which go in row t of F. Each
    # sector factor is the average residual of the stocks in that sector on that day -
    B = sector_matrix(universe.sectors, universe.sector_names);
    number_of_sectors = length(universe.sector_names);
    F = zeros(number_of_days, number_of_sectors);
    for t ∈ 1:number_of_days
        F[t, :] = least_squares_fit(B, E[t, :]);
    end

    # Fitting step 3, for each stock i: fit the residual of stock i to the sector factors F. The fit gives
    # the sector loadings δ_i, which go in column i of Δ. The part of the residual that the sector factors
    # do not explain is the stock-specific part, which goes in column i of U -
    Δ = zeros(number_of_sectors, number_of_stocks);
    U = zeros(number_of_days, number_of_stocks);
    for i ∈ 1:number_of_stocks
        δ = least_squares_fit(F, E[:, i]);
        Δ[:, i] = δ;
        U[:, i] = E[:, i] - F * δ;
    end

    # Return every piece of the fit by name, so that the caller can read fit.X, fit.Θ, fit.U, and so on -
    return (X = X, Θ = Θ, E = E, F = F, Δ = Δ, U = U);
end

"""
    fit_jump_model(series::Vector{Float64}, settings::NamedTuple) -> JumpHMM.MyJumpHiddenMarkovModel

Fit a single-asset jump hidden Markov model to one series, as in the L13a and L14a examples, with
the jump settings of the tuned SPY model and no tuning.

### Arguments

- `series`: A daily series: a factor, or the stock-specific part of a stock.
- `settings`: The settings from `load_config`. The function uses `number_of_states`, `ν`, `ϵ`,
  `λ`, and `Δt`.

### Returns

- The fitted jump hidden Markov model of the series.
"""
function fit_jump_model(series::Vector{Float64}, settings::NamedTuple)::JumpHMM.MyJumpHiddenMarkovModel

    # Build the model with the course package JumpHMM. JumpHMM.build takes the type of model to build, and
    # a NamedTuple of its inputs: the series, the number of hidden states, the degrees of freedom ν of the
    # Student-t distribution of each state, the probability ϵ that a jump episode starts on a given day,
    # the mean length λ of a jump episode (days), and the time step Δt (yr) -
    return JumpHMM.build(JumpHMM.MyJumpHiddenMarkovModel, (growth_rates = series,
        number_of_states = settings.number_of_states, ν = settings.ν, ϵ = settings.ϵ, λ = settings.λ,
        Δt = settings.Δt));
end

"""
    draw_series(model::JumpHMM.MyJumpHiddenMarkovModel, number_of_days::Int) -> Vector{Float64}

Draw one synthetic path of a series from its jump hidden Markov model.

### Arguments

- `model`: The model from `fit_jump_model`.
- `number_of_days`: The length of the path.

### Returns

- The synthetic path, one value per day.
"""
function draw_series(model::JumpHMM.MyJumpHiddenMarkovModel, number_of_days::Int)::Vector{Float64}

    # Draw one path of number_of_days days. JumpHMM.simulate returns a NamedTuple whose field growth_rates
    # holds one column per path; [:, 1] keeps the column of the one path -
    return JumpHMM.simulate(model, number_of_days; number_of_paths = 1).growth_rates[:, 1];
end

"""
    synthetic_markets(fit::NamedTuple, settings::NamedTuple; cholesky_step::Bool = false) -> Vector{Matrix{Float64}}

Draw synthetic markets from a fitted factor model: one single-asset jump hidden Markov model for
each factor and one for the stock-specific part of each stock. Each synthetic market is as long as
the data.

Without the Cholesky step, each factor gets its own jump hidden Markov model, and the draws are the
synthetic factors. With the Cholesky step, `unmix_factors` runs first (fitting step 4), each column
of `Z` gets its own model, and `mix_factors` turns the draws back into factors (sampling step 1).

### Arguments

- `fit`: The fitted model from `fit_factor_model`.
- `settings`: The settings from `load_config`. The function uses `number_of_paths`, `seed`, and the
  settings of `fit_jump_model`.

### Optional Arguments

- `cholesky_step`: `true` runs the Cholesky step. Default: `false`.

### Returns

- `settings.number_of_paths` synthetic markets, each a matrix of growth rates, days × stocks (1/yr).
"""
function synthetic_markets(fit::NamedTuple, settings::NamedTuple; cholesky_step::Bool = false)::Vector{Matrix{Float64}}

    # Initialize: the number of days and stocks, and the number of columns of X after its column of ones,
    # which is g_m plus one column for each economic factor -
    number_of_days = size(fit.U, 1);
    number_of_stocks = size(fit.U, 2);
    number_of_market_columns = size(fit.X, 2) - 1; # g_m and the economic factors

    # The factor matrix Φ = [g_m, x_1, ..., x_K, F]: every column of X except the column of ones, then the
    # sector factors. fit.X[:, 2:end] keeps the columns of X from column 2 to the last column -
    Φ = hcat(fit.X[:, 2:end], fit.F);

    # Fitting step 4, with the Cholesky step only: unmix the factors. Without the Cholesky step, the jump
    # hidden Markov models fit the columns of Φ, and μ and A stay empty because nothing uses them. With the
    # Cholesky step, unmix_factors returns three values, which (μ, A, Z) = ... unpacks in order, and the
    # jump hidden Markov models fit the uncorrelated factors Z instead -
    series = Φ;
    μ = Float64[];
    A = zeros(0, 0);
    if cholesky_step == true
        (μ, A, Z) = unmix_factors(Φ);
        series = Z;
    end

    # Fitting step 5: one jump hidden Markov model for each column of series, then one for the
    # stock-specific part of each stock. Each list starts empty, and push! adds one model at a time -
    factor_models = JumpHMM.MyJumpHiddenMarkovModel[];
    for j ∈ 1:size(series, 2)
        push!(factor_models, fit_jump_model(series[:, j], settings));
    end
    stock_models = JumpHMM.MyJumpHiddenMarkovModel[];
    for i ∈ 1:number_of_stocks
        push!(stock_models, fit_jump_model(fit.U[:, i], settings));
    end

    # Fix the seed of the random numbers, so that every run draws the same synthetic markets. markets
    # starts as an empty list of matrices, and each pass of the loop adds one synthetic market -
    Random.seed!(settings.seed);
    markets = Matrix{Float64}[];
    for path ∈ 1:settings.number_of_paths

        # Sampling step 1: draw a path from each factor model, one column per model. Without the Cholesky
        # step, the draws are the synthetic factors. With the Cholesky step, the draws are columns of Z,
        # and mix_factors turns them back into correlated factors -
        draws = zeros(number_of_days, size(series, 2));
        for j ∈ 1:size(series, 2)
            draws[:, j] = draw_series(factor_models[j], number_of_days);
        end
        Φ_synthetic = draws;
        if cholesky_step == true
            Φ_synthetic = mix_factors(draws, μ, A);
        end

        # Split the synthetic factors in the same order as Φ. The first columns, with a new column of ones
        # in front, give the synthetic design matrix [1, g_m, x_1, ..., x_K]. The remaining columns are the
        # synthetic sector factors; (number_of_market_columns + 1):end runs from the first of them to the last -
        X_synthetic = hcat(ones(number_of_days), Φ_synthetic[:, 1:number_of_market_columns]);
        F_synthetic = Φ_synthetic[:, (number_of_market_columns + 1):end];

        # Sampling steps 2 and 3, for each stock i: draw the stock-specific part u from the model of stock i,
        # then compose the synthetic growth rates of stock i from the synthetic factors and the loadings
        # that fitting steps 1 and 3 found for stock i (column i of Θ and column i of Δ) -
        G_synthetic = zeros(number_of_days, number_of_stocks);
        for i ∈ 1:number_of_stocks
            u = draw_series(stock_models[i], number_of_days);
            G_synthetic[:, i] = compose_growth_rates(X_synthetic, fit.Θ[:, i], F_synthetic, fit.Δ[:, i], u);
        end

        # Keep this synthetic market, then draw the next one -
        push!(markets, G_synthetic);
    end

    return markets;
end

"""
    market_statistics(G::Matrix{Float64}, universe::NamedTuple, settings::NamedTuple) -> NamedTuple

Measure how the stocks of one market move together, real or synthetic: the numbers that the table
'Real and synthetic markets' reports for that market.

### Arguments

- `G`: The growth rates of the stocks (1/yr), days × stocks, real or synthetic.
- `universe`: The market from `load_universe`. The function uses `sectors`.
- `settings`: The settings from `load_config`. The function uses `pair_first` and `pair_second`.

### Returns

- A `NamedTuple` with the fields:
  - `same_sector`: The average correlation of two different stocks in the same sector.
  - `different_sectors`: The average correlation of two stocks in different sectors.
  - `pairs`: For each pair of sectors, the average correlation of a stock in the first sector and a
    stock in the second sector.
"""
function market_statistics(G::Matrix{Float64}, universe::NamedTuple, settings::NamedTuple)::NamedTuple

    # Initialize: cor(G) correlates every pair of columns of G, so C[i, j] is the correlation of the
    # growth rates of stocks i and j over all the days. sectors[i] is the sector of stock i -
    C = cor(G);
    number_of_stocks = size(G, 2);
    sectors = universe.sectors;

    # Add up the correlations of two different stocks in the same sector, and of two stocks in different
    # sectors, and count the pairs of each kind. The inner loop starts at j = i + 1, so it visits each pair
    # of stocks once and skips the pair of a stock with itself -
    same_total = 0.0;
    same_count = 0;
    different_total = 0.0;
    different_count = 0;
    for i ∈ 1:number_of_stocks
        for j ∈ (i + 1):number_of_stocks
            if sectors[i] == sectors[j]
                same_total = same_total + C[i, j];
                same_count = same_count + 1;
            else
                different_total = different_total + C[i, j];
                different_count = different_count + 1;
            end
        end
    end

    # For each pair of sectors k, average the correlation of every stock i in the first sector with every
    # stock j in the second sector -
    number_of_pairs = length(settings.pair_first);
    pairs = zeros(number_of_pairs);
    for k ∈ 1:number_of_pairs
        pair_total = 0.0;
        pair_count = 0;
        for i ∈ 1:number_of_stocks
            for j ∈ 1:number_of_stocks
                if sectors[i] == settings.pair_first[k] && sectors[j] == settings.pair_second[k]
                    pair_total = pair_total + C[i, j];
                    pair_count = pair_count + 1;
                end
            end
        end
        pairs[k] = pair_total / pair_count;
    end

    # Divide each total by its count to get the averages, and return them by name -
    return (same_sector = same_total / same_count, different_sectors = different_total / different_count,
        pairs = pairs);
end

"""
    range_statistics(markets::Vector{Matrix{Float64}}, universe::NamedTuple, settings::NamedTuple) -> NamedTuple

Find the lowest and the highest value of each statistic of `market_statistics` over the synthetic
markets of one model.

### Arguments

- `markets`: The synthetic markets from `synthetic_markets`.
- `universe`: The market from `load_universe`.
- `settings`: The settings from `load_config`.

### Returns

- A `NamedTuple` with the fields `lowest` and `highest`. Each holds the fields of `market_statistics`:
  `lowest` holds the lowest value of each statistic over the markets, and `highest` the highest value.
"""
function range_statistics(markets::Vector{Matrix{Float64}}, universe::NamedTuple, settings::NamedTuple)::NamedTuple

    # Start from the statistics of the first synthetic market: for now, its values are both the lowest
    # and the highest. copy gives the low and the high list of pairs their own values -
    first_statistics = market_statistics(markets[1], universe, settings);
    low_same = first_statistics.same_sector;
    high_same = first_statistics.same_sector;
    low_different = first_statistics.different_sectors;
    high_different = first_statistics.different_sectors;
    low_pairs = copy(first_statistics.pairs);
    high_pairs = copy(first_statistics.pairs);

    # Compare each other synthetic market with the values so far: min keeps the smaller of two numbers,
    # and max keeps the larger -
    for m ∈ 2:length(markets)
        statistics = market_statistics(markets[m], universe, settings);
        low_same = min(low_same, statistics.same_sector);
        high_same = max(high_same, statistics.same_sector);
        low_different = min(low_different, statistics.different_sectors);
        high_different = max(high_different, statistics.different_sectors);
        for k ∈ 1:length(low_pairs)
            low_pairs[k] = min(low_pairs[k], statistics.pairs[k]);
            high_pairs[k] = max(high_pairs[k], statistics.pairs[k]);
        end
    end

    # Group the lowest values and the highest values, each with the field names of market_statistics -
    lowest = (same_sector = low_same, different_sectors = low_different, pairs = low_pairs);
    highest = (same_sector = high_same, different_sectors = high_different, pairs = high_pairs);
    return (lowest = lowest, highest = highest);
end

"""
    r_squared(g::Vector{Float64}, residual::Vector{Float64}) -> Float64

The fraction of the variance of a stock's growth rates that a fit explains.

### Arguments

- `g`: The growth rates of the stock.
- `residual`: The part of `g` that the fit does not explain.

### Returns

- `1 - var(residual) / var(g)`: `1` for a perfect fit, `0` for a fit that explains nothing.
"""
function r_squared(g::Vector{Float64}, residual::Vector{Float64})::Float64

    # var is the sample variance. One minus the fraction of the variance that the fit leaves in the
    # residual is the fraction that the fit explains -
    return 1.0 - var(residual) / var(g);
end
